                try{frame=NavPreparedCrowdStep.Create(s.Crowd,s.Crowd.Units.Count,r);frame.Observe();var installed=frame.Source.Select(a=>a.StorageOwner.InstalledExecution as NavigationInstalledExecutionOwner).ToArray();var detached=frame.Source.Select(a=>a.StorageOwner.InstalledDetached).ToArray();next=GroupMarch.PrepareOwned(frame,source,installed,detached,memberships,4,source.Data.MarchProfileRevision,1d/30,r,true);Joint(frame,source);Stale(s,source,installed,detached,memberships,r);Atomic(s,source);Check(ReferenceEquals(live.ImmutableVersion,source)&&s.GroupFor(3).FormationSeal==source.Formation.Seal,"Private boundary work published source mutation");}
