    static void Joint(NavPreparedCrowdStep frame,NavigationAuthorityGroup source)
    {
        var bodies=new NavMotionBody[frame.After.Length];var proposals=new NavMotionProposal[bodies.Length];int focus=-1,other=-1;double dt=2;
        for(int i=0;i<bodies.Length;i++){var a=frame.After[i];bodies[i]=new NavMotionBody{Id=a.Id,Position=a.Position,Target=a.Position,Heading=a.Heading,Radius=a.Radius,Speed=a.Speed,TurnSpeed=a.TurnSpeed};proposals[i]=new NavMotionProposal{Position=a.Position};}
        bool Clear(int row,NavPoint to)=>frame.RecastRoutes[row]!=null&&NavRecastIntervals.Advance(frame.RecastRoutes[row],frame.RecastStates[row],frame.After[row].Location,to,frame.Reservation,out _,frame.Working,frame.After[row].Id);
        foreach(var entry in source.Formation.Entries.Where(e=>e.Stage==RecastPassageStage.Staging)){
            int i=frame.Find(entry.Entity);if(i<0||frame.RecastRoutes[i]==null)continue;
            for(int j=0;j<bodies.Length;j++)if(i!=j&&frame.RecastRoutes[j]!=null&&frame.After[i].Location.SurfaceId==frame.After[j].Location.SurfaceId){double length=Distance(bodies[i].Position,bodies[j].Position);if(length<2||length>4)continue;double x=(bodies[j].Position.X-bodies[i].Position.X)/length,z=(bodies[j].Position.Z-bodies[i].Position.Z)/length;var a=new NavPoint(bodies[i].Position.X-.4*x,bodies[i].Position.Z-.4*z);var b=new NavPoint(bodies[i].Position.X+.8*x,bodies[i].Position.Z+.8*z);if(Distance(bodies[j].Position,b)>bodies[j].Speed*dt||!Clear(i,a)||!Clear(j,b))continue;
                var control=(NavMotionProposal[])proposals.Clone();control[i].Position=a;control[j].Position=b;control[i].Velocity=new NavPoint((a.X-bodies[i].Position.X)/dt,(a.Z-bodies[i].Position.Z)/dt);control[j].Velocity=new NavPoint((b.X-bodies[j].Position.X)/dt,(b.Z-bodies[j].Position.Z)/dt);var trial=(NavMotionBody[])bodies.Clone();trial[i].Active=trial[j].Active=true;NavCrowdMotion.ResolveJoint(trial,control,dt);if(!control[i].Position.Equals(a)||!control[j].Position.Equals(b))continue;focus=i;other=j;bodies=trial;proposals=control;break;
            }if(focus>=0)break;
        }
        Check(focus>=0&&other>=0,"No physically certified cancellation/joint control pair");var hints=(NavFormationFrameHint[])frame.Formation.Clone();try{Array.Clear(frame.Formation,0,frame.Formation.Length);frame.Formation[focus]=new NavFormationFrameHint{Flags=NavFormationFrameHint.Wait};typeof(NavCrowd).GetMethod("FilterRecastSweeps",Hidden).Invoke(frame.Working,new object[]{dt,bodies,proposals});double gap=Distance(proposals[focus].Position,proposals[other].Position);Console.WriteLine(JsonConvert.SerializeObject(new{Case="policy-cancel-joint-fixedpoint-before-assert",Focus=bodies[focus].Id,Other=bodies[other].Id,Gap=gap,Required=bodies[focus].Radius+bodies[other].Radius,FocusCancelled=proposals[focus].Position.Equals(bodies[focus].Position),OtherRetracted=!proposals[other].Position.Equals(new NavPoint(bodies[focus].Position.X+(bodies[other].Position.X-bodies[focus].Position.X)/Distance(bodies[focus].Position,bodies[other].Position)*.8,bodies[focus].Position.Z+(bodies[other].Position.Z-bodies[focus].Position.Z)/Distance(bodies[focus].Position,bodies[other].Position)*.8))}));Check(proposals[focus].Position.Equals(bodies[focus].Position)&&(frame.Formation[focus].Flags&NavFormationFrameHint.PolicyWait)!=0&&gap>=bodies[focus].Radius+bodies[other].Radius-1e-9,"Policy cancellation did not preserve joint safety fixed point");}
        finally{Array.Copy(hints,frame.Formation,hints.Length);}
    }
    static void Stale(NavigationSession s,NavigationAuthorityGroup source,NavigationInstalledExecutionOwner[] installed,bool[] detached,NavigationCommandSlots<int,long> memberships,INavStorageReservation r)
    {
        NavPreparedCrowdStep frame=null;NavigationAuthorityGroup unexpected=null;bool refused=false;
        try{frame=NavPreparedCrowdStep.Create(s.Crowd,s.Crowd.Units.Count,r);frame.Observe();var changed=(NavigationInstalledExecutionOwner[])installed.Clone();var rows=Enumerable.Range(0,changed.Length).Where(i=>changed[i]!=null).Take(2).ToArray();changed[rows[0]]=changed[rows[1]];try{unexpected=GroupMarch.PrepareOwned(frame,source,changed,detached,memberships,4,source.Data.MarchProfileRevision,1d/30,r,true);}catch(ArgumentException error)when(error.Message=="Formation accepted route binding changed."){refused=true;}Check(refused&&unexpected==null,"Stale accepted mapping not rejected exactly");Console.WriteLine("{\"Case\":\"stale-accepted-request-binding\",\"Result\":\"PASS\"}");}
        finally{unexpected?.ReleaseStorage();frame?.Release();}
