    static void Atomic(NavigationSession s,NavigationAuthorityGroup source)
    {
        var budget=s.PhysicalHostBudget;long physical=budget.PhysicalBytes,held=budget.HeldBytes;int active=budget.ActiveScopes;long layout=(long)typeof(RecastFormationPlan).GetMethod("Layout",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{source.Members.Count,0});long deny=NavStorageLayout.Charge(layout);int denials=0;bool refused=false;
        Check(budget.TryOpenScope(NavigationPreparationKind.Solve,805,0,out var scope),"Refusal scope unavailable");using(scope){RecastFormationPlan unexpected=null;budget.AllocationAdmission=value=>{if(value==deny){denials++;return false;}return true;};try{try{unexpected=RecastFormationPlan.Collect(source.Data,source.Members,scope.OwnedReservation());}catch(InvalidOperationException error)when(error.GetType()==typeof(InvalidOperationException)&&error.Message=="Physical storage exceeds prepared reservation."){refused=true;}Check(refused&&unexpected==null&&denials==1,"Exact formation ownedbirth refusal not reached");}finally{budget.AllocationAdmission=null;unexpected?.Release();}}
        Check(budget.PhysicalBytes==physical&&budget.HeldBytes==held&&budget.ActiveScopes==active,"Denied formation birth leaked owner/credits");bool published=false,cancelled=false;Check(budget.TryOpenScope(NavigationPreparationKind.Solve,805,0,out scope),"Cancellation scope unavailable");using(scope){RecastFormationPlan plan=null;NavigationAuthorityGroup candidate=null;try{plan=RecastFormationPlan.Collect(source.Data,source.Members,scope.OwnedReservation());candidate=NavigationAuthorityGroup.CopyWithFormationOwned(source,plan,scope.OwnedReservation());scope.Attach(candidate);scope.RequestCancel();try{scope.Publish(candidate,_=>published=true);}catch(OperationCanceledException error)when(error.Message=="Navigation preparation was cancelled."){cancelled=true;}Check(cancelled&&!published,"Cancelled formation COW published");}finally{candidate?.ReleaseStorage();plan?.Release();}}
        Check(budget.PhysicalBytes==physical&&budget.HeldBytes==held&&budget.ActiveScopes==active,"Cancelled formation birth leaked owner/credits");Console.WriteLine(JsonConvert.SerializeObject(new{Case="formation-atomic-refusal-cancel",Result="PASS",DeniedBirthBytes=deny,Denials=denials,Published=published,Physical=physical,Held=held,Scopes=active}));
    }
